    // Calculate SDF alpha
    let sdf_alpha = smoothstep(0.5 - tileProps.sdfgamma / in.v_floorwidth, 0.5 + tileProps.sdfgamma / in.v_floorwidth, sdfdist);

    return in.v_color * (alpha * in.v_opacity * sdf_alpha);
